package com.google.javascript.jscomp;

import com.google.javascript.jscomp.CheckLevel;
import com.google.javascript.jscomp.NodeTraversal.Callback;
import com.google.javascript.jscomp.errors.ErrorReporter;
import com.google.javascript.rhino.JSDocInfo;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentMatchers;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class CheckGlobalThis_shouldTraverse_TriageGen1Test {

    private CheckGlobalThis checkGlobalThis;
    private NodeTraversal mockTraversal;

    @Before
    public void setUp() {
        // CheckGlobalThis typically requires a Compiler or similar in real scenarios, 
        // but for unit testing this method, we instantiate it directly.
        checkGlobalThis = new CheckGlobalThis();
        mockTraversal = mock(NodeTraversal.class);
    }

    // Helper to create mock nodes
    private Node createNode(int type, String value) {
        Node node = mock(Node.class);
        when(node.getType()).thenReturn(type);
        if (value != null) {
            when(node.getString()).thenReturn(value);
        }
        return node;
    }

    @Test
    public void testNonFunctionNodeReturnsTrue() {
        Node n = createNode(Token.VAR, null);
        Node parent = createNode(Token.BLOCK, null);
        assertTrue(checkGlobalThis.shouldTraverse(mockTraversal, n, parent));
    }

    @Test
    public void testFunctionNodeWithJsDocConstructorReturnsFalse() {
        Node n = createNode(Token.FUNCTION, null);
        Node parent = createNode(Token.BLOCK, null);

        // Mock getFunctionJsDocInfo via a spy or by ensuring the node returns info if possible.
        // Since getFunctionJsDocInfo is private/protected, we assume it's tested via its side effects.
        // If we cannot mock the internal call, we must rely on the fact that 
        // if jsDoc is null, it moves to the next check.

        // Case: jsDoc is null
        assertTrue(checkGlobalThis.shouldTraverse(mockTraversal, n, parent));
    }

    @Test
    public void testFunctionNodeWithInvalidParentTypeReturnsFalse() {
        Node n = createNode(Token.FUNCTION, null);
        Node parent = createNode(Token.STRING, null); // Not BLOCK, SCRIPT, NAME, or ASSIGN

        // Note: This assumes getFunctionJsDocInfo returns null for this test case
        assertFalse(checkGlobalThis.shouldTraverse(mockTraversal, n, parent));
    }

    @Test
    public void testFunctionNodeWithValidParentTypeReturnsTrue() {
        Node n = createNode(Token.FUNCTION, null);
        Node parent = createNode(Token.ASSIGN, null);

        assertTrue(checkGlobalThis.shouldTraverse(mockTraversal, n, parent));
    }

    @Test
    public void testAssignmentLhsTraverses() {
        Node n = createNode(Token.NAME, "a");
        Node lhs = createNode(Token.NAME, "a");
        Node parent = createNode(Token.ASSIGN, null);

        when(parent.getFirstChild()).thenReturn(lhs);
        when(lhs.getNext()).thenReturn(createNode(Token.ASSIGN, null)); // rhs

        // When n is lhs, it should return true and set assignLhsChild
        assertTrue(checkGlobalThis.shouldTraverse(mockTraversal, n, parent));
    }

    @Test
    public void testAssignmentRhsPrototypeGetPropReturnsFalse() {
        Node n = createNode(Token.NAME, "b");
        Node lhs = createNode(Token.GETPROP, null);
        Node prototypeChild = createNode(Token.NAME, "prototype");
        Node parent = createNode(Token.ASSIGN, null);

        when(parent.getFirstChild()).thenReturn(lhs);
        when(lhs.getNext()).thenReturn(n);
        when(lhs.getLastChild()).thenReturn(prototypeChild);
        when(NodeUtil.isGet(lhs)).thenReturn(true);
        when(lhs.getType()).thenReturn(Token.GETPROP);
        when(prototypeChild.getString()).thenReturn("prototype");

        assertFalse(checkGlobalThis.shouldTraverse(mockTraversal, n, parent));
    }

    @Test
    public void testAssignmentRhsNestedPrototypeGetPropReturnsFalse() {
        Node n = createNode(Token.NAME, "b");
        Node lhs = createNode(Token.GETPROP, null);
        Node llhs = createNode(Token.GETPROP, null);
        Node prototypeChild = createNode(Token.NAME, "prototype");
        Node parent = createNode(Token.ASSIGN, null);

        when(parent.getFirstChild()).thenReturn(lhs);
        when(lhs.getNext()).thenReturn(n);
        when(NodeUtil.isGet(lhs)).thenReturn(true);
        when(lhs.getType()).thenReturn(Token.GETPROP);
        when(lhs.getFirstChild()).thenReturn(llhs);
        when(llhs.getType()).thenReturn(Token.GETPROP);
        when(llhs.getLastChild()).thenReturn(prototypeChild);
        when(prototypeChild.getString()).thenReturn("prototype");

        assertFalse(checkGlobalThis.shouldTraverse(mockTraversal, n, parent));
    }

    @Test
    public void testAssignmentRhsNormalReturnsTrue() {
        Node n = createNode(Token.NAME, "b");
        Node lhs = createNode(Token.NAME, "a");
        Node parent = createNode(Token.ASSIGN, null);

        when(parent.getFirstChild()).thenReturn(lhs);
        when(lhs.getNext()).thenReturn(n);
        when(NodeUtil.isGet(lhs)).thenReturn(false);

        assertTrue(checkGlobalThis.shouldTraverse(mockTraversal, n, parent));
    }

    @Test
    public void testAssignmentRhsGetPropButNotPrototypeReturnsTrue() {
        Node n = createNode(Token.NAME, "b");
        Node lhs = createNode(Token.GETPROP, null);
        Node propName = createNode(Token.NAME, "x");
        Node parent = createNode(Token.ASSIGN, null);

        when(parent.getFirstChild()).thenReturn(lhs);
        when(lhs.getNext()).thenReturn(n);
        when(NodeUtil.isGet(lhs)).thenReturn(true);
        when(lhs.getType()).thenReturn(Token.GETPROP);
        when(lhs.getLastChild()).thenReturn(propName);
        when(propName.getString()).thenReturn("x");

        assertTrue(checkGlobalThis.shouldTraverse(mockTraversal, n, parent));
    }

    @Test
    public void testNullParentReturnsTrue() {
        Node n = createNode(Token.NAME, "a");
        assertTrue(checkGlobalThis.shouldTraverse(mockTraversal, n, null));
    }
}
